from lib import *
S = SS('g6')
steps = [
    step("s = \"a好😀é\" 的 len 是 10 字节,utf8.RuneCountInString 是 4 个 rune。按下标遍历得到 10 个字节(0x61 e5 a5 bd f0 9f 98 80 c3 a9);for i, r := range s 得到 4 个 rune,下标依次是 0、1、4、8,宽度 1、3、4、2 字节;[]rune(s) 长度 4,rs[2] 是 U+1F600。EncodeRune:U+0061 1 字节、U+00E9 2 字节、U+597D 3 字节、U+1F600 与 U+10FFFF 4 字节;U+D800 与 U+110000 不是合法 rune,编码成 3 字节 ef bf bd(U+FFFD)。'a' 的类型是 int32;😀 在 UTF-16 里是 D83D DE00 两个单元。", t=tl(S(1)), done=lidx(S(1), 's = \"a好😀é\"', '按下标遍历', 'for i, r := range s'), mark=lidx(S(1), 'EncodeRune(U+D800)', 'EncodeRune(U+110000)', 'UTF-16'), kv=KV([['len(s) / rune 数', '10 字节 / 4 个'], ['range 的下标', '0、1、4、8(是字节偏移)'], ['rune 宽度', '1 / 2 / 3 / 4 字节(a / é / 好 / 😀)'], ['U+D800、U+110000', '编码成 ef bf bd = U+FFFD']], ['range 的下标'])),
    step("非法 UTF-8 不会让 range 出错:bad = \"ab\\xffcd\\xe5\\xa5\" 不合法;range 得到 7 个 rune,孤立的 0xff 与被截断的 0xe5、0xa5 各变成一个 U+FFFD(宽度 1);[]rune(bad) 长度 7,再转回 string 与原串不相等。\"好\" 是 3 字节,h[:2] 不合法;\"你好世界\"[:4] 按字节截得到 \"你\\xe5\"(不合法),用 utf8.RuneStart 回退的 cut 得到 \"你\"(合法)。string(rune(0xD800)) 与 string(rune(-1)) 都是 U+FFFD。", t=tl(S(2)), done=lidx(S(2), 'bad = ', 'for i, r := range bad', '[]rune(bad)'), mark=lidx(S(2), 'h[:2]', '按字节截', 'string(rune(0xD800))'), kv=KV([['range 非法 UTF-8', '每个坏字节 → 一个 U+FFFD,宽度 1'], ['string([]rune(bad)) == bad', 'false(坏字节已被替换)'], ['\"你好世界\"[:4]', '\"你\\xe5\",不合法'], ['cut(s, 4)', '\"你\",合法']], ['\"你好世界\"[:4]'])),
    step("看起来一样的字符串:预组合的 é(U+00E9)与 e + 组合重音符号(U+0301)显示相同,== 比较是 false;长度 2 与 3 字节,rune 数 1 与 2。国旗 🇨🇳 是 8 字节、2 个 rune;用零宽连接符拼成的家庭 emoji 是 18 字节、5 个 rune。rune 数不等于人眼看到的字符数。", t=tl(S(3)), done=lidx(S(3), '显示相同'), mark=lidx(S(3), '国旗', '家庭 emoji'), kv=KV([['é 与 e + U+0301', '== 为 false;2 / 3 字节;1 / 2 个 rune'], ['🇨🇳', '8 字节,2 个 rune'], ['家庭 emoji(ZWJ 序列)', '18 字节,5 个 rune']], ['é 与 e + U+0301'])),
    step("遍历 1000 个汉字(3000 字节)的成本:for range str 中位 2221.95 ns/op;逐字节下标遍历 887.32 ns/op;先 []rune(str) 再遍历 5015.55 ns/op;utf8.RuneCountInString 2127.29 ns/op;len([]rune(str)) 2075.91 ns/op。AllocsPerRun:for range str 0 次,[]rune(str) 后遍历 1 次,len([]rune(str)) 0 次(编译器没有真的建 []rune)。", t=tl(S(4)), done=lidx(S(4), 'for range str', '逐字节'), mark=lidx(S(4), 'for range []rune', 'len([]rune(str))', 'AllocsPerRun'), b=bars([['逐字节 ns', 887.32, '887'], ['for range str ns', 2221.95, '2222'], ['len([]rune(str)) ns', 2075.91, '2076'], ['先转 []rune 再遍历 ns', 5015.55, '5016']], 5015.55, done=[0, 1], mark=[3]), kv=KV([['for range str', '2221.95 ns/op,0 次分配'], ['逐字节遍历', '887.32 ns/op'], ['先转 []rune 再遍历', '5015.55 ns/op,1 次分配'], ['len([]rune(str))', '2075.91 ns/op,0 次分配']], ['先转 []rune 再遍历'])),
    step("go vet 对 n := 65; s := string(n) 报 conversion from int to string yields a string of one rune, not a string of digits(rc=1);而 go build 通过,运行输出 'A'——整数转字符串得到的是码点对应的字符,不是数字的文本。", t=tl(S(5)), done=lidx(S(5), 'go build'), mark=lidx(S(5), 'go vet'), kv=KV([['string(65)', '\"A\"(码点 65 的字符)'], ['go vet', 'rc=1,conversion from int to string yields a string of one rune'], ['要得到 \"65\"', '用 strconv.Itoa 或 fmt.Sprint']], ['go vet'])),
]
A = mkartg('g6', 6, 'Go,UTF-8,rune,字符串,range,真实验证,动画演示',
    '用 Go 1.27.1 实测字符串的字节与 rune:range 的下标是字节偏移、遍历得到 rune,非法 UTF-8 变成 U+FFFD,按字节截断会切坏字符,预组合 é 与 e+重音符号 == 为 false,国旗与家庭 emoji 的 rune 数不等于看到的字符数;1000 个汉字 range 2222 ns 对逐字节 887 ns,先转 []rune 5016 ns;go vet 对 string(int) 的警告。',
    'Go 的字符串是字节序列,range 却按 rune 遍历。两者的差别在中文、emoji 和非法字节上最明显。这篇逐个现象用真实输出验证:下标与偏移、非法字节怎么处理、截断为什么会出乱码、哪些“同一个字符”其实不相等,以及不同遍历方式的成本。',
    [('字节偏移', 'range 返回的下标是字节偏移:\"a好😀é\" 的下标是 0、1、4、8'), ('U+FFFD', '非法或被截断的字节在 range 里各变成一个替换字符,宽度 1'), ('2222 ns vs 887 ns', '1000 个汉字 for range 与逐字节遍历的耗时')],
    [('字节与 rune', '<p>下标 <code>s[i]</code> 是第 <code>i</code> 个<b>字节</b>,<code>for i, r := range s</code> 是按 UTF-8 解码出的 <b>rune</b>,下标是它的起始字节偏移。UTF-8 里一个 rune 占 1 到 4 字节;<code>U+10FFFF</code> 是最大的合法码点,代理区(<code>U+D800</code> 起)与超过上限的值不是合法 rune,编码时会得到 <code>U+FFFD</code>。</p>'),
     ('非法字节与截断', '<p><code>range</code> 遇到非法序列不会 panic,而是产生 <code>U+FFFD</code> 并只前进 1 字节,所以被截断的多字节字符的每个残留字节各变成一个替换字符(上面的 7 个 rune)。因此“字符串 → []rune → 字符串”并不总是原样往返。截断字符串时要在 rune 边界上切:<code>utf8.RuneStart</code> 能判断某个字节是不是一个 rune 的开头。</p>'),
     ('同一个字符,不同的字节', '<p>Go 的字符串比较是逐字节的,不做 Unicode 规范化。所以预组合的 <code>é</code> 与“<code>e</code> + 组合重音符号”<code>==</code> 为 <code>false</code>。要按人眼看到的字符计数或比较,需要规范化与字素簇切分,这在标准库里没有(<code>golang.org/x/text</code> 里有,本文没有安装与试用)。</p>'),
     ('遍历的成本', '<p><code>for range str</code> 要边走边解码,比逐字节慢,但不分配;先转 <code>[]rune</code> 再遍历既要分配 4 字节 × rune 数的内存又要多走一遍,最慢。<code>len([]rune(str))</code> 看起来会分配,实际是 0 次分配、耗时与 <code>utf8.RuneCountInString</code> 接近——编译器没有真的建 <code>[]rune</code>(我没有去看是哪条优化起的作用)。</p>'),
     ('string(int) 的陷阱', '<p><code>string(n)</code> 把整数当码点,不是转十进制文本。这个误用足够常见,所以 <code>go vet</code> 专门检查它。要得到数字的文本,用 <code>strconv.Itoa(n)</code> 或 <code>fmt.Sprint(n)</code>。</p>')],
    steps,
    [ENV_G + '。基准测试每个变体 7 轮取中位数,字符串是 1000 个连续汉字(U+4E00 起);go vet 用 Go 1.27.1 自带的默认检查集',
     '没有验证:Unicode 规范化与字素簇切分(golang.org/x/text、rivo/uniseg 本机没有安装)、utf8.DecodeRune 与 range 的汇编差异、纯 ASCII 字符串的 range 快路径、amd64 上的耗时'],
    'rune 与 UTF-8')
